 async function loadSenders(){try{senders=items(await request('/delivery/senders','POST',params()));el('ds-sender').innerHTML='<option value="">—</option>'+senders.map(v=>`<option value="${esc(v.Ref)}">${esc(v.Description||v.FirstName||v.Ref)}</option>`).join('');if(senderRef)el('ds-sender').value=senderRef;await loadContacts()}catch(e){el('ds-error').textContent=e.message}}
