const propertyLabels={uk:{apartment:'Квартира',house:'Будинок',room:'Кімната',commercial:'Комерційна нерухомість',garage:'Гараж',land:'Ділянка',other:'Інше'},ru:{apartment:'Квартира',house:'Дом',room:'Комната',commercial:'Коммерческая недвижимость',garage:'Гараж',land:'Участок',other:'Другое'}};
const propertyOptions=(value,all=false)=>(all?`<option value="">${t('all')}</option>`:'')+Object.entries(propertyLabels[state.lang]).map(([k,v])=>`<option value="${k}" ${value===k?'selected':''}>${v}</option>`).join('');
const typeField=(value,all=false)=>`<label class="fl" for="dm-property">${state.lang==='ru'?'Тип недвижимости':'Тип нерухомості'}</label><select id="dm-property" name="property_type">${propertyOptions(value,all)}</select>`;
const originalNewListing=newListing;newListing=function(){originalNewListing();const s=SH[SH.length-1];if(s)s.querySelector('#n1')?.insertAdjacentHTML('beforebegin',typeField('apartment'))};
const originalEditSheet=editSheet;editSheet=function(id){originalEditSheet(id);const s=SH[SH.length-1],l=HL.find(x=>x.id===id);if(s&&l)s.querySelector('#e1')?.insertAdjacentHTML('beforebegin',typeField(l.property_type||'apartment'))};
const originalFilterSheet=filterSheet;filterSheet=function(){originalFilterSheet();const s=SH[SH.length-1];s.querySelector('.h1')?.insertAdjacentHTML('afterend',typeField(rentalProperty,true));s.addEventListener('click',e=>{if(e.target.closest('#fo'))rentalProperty=s.querySelector('#dm-property').value;if(e.target.closest('#fr'))rentalProperty=''},true)};
const originalApi=api;api=function(path,options={}){if(path.startsWith('/api/listings?')&&rentalProperty)path+='&property_type='+encodeURIComponent(rentalProperty);const selector=SH[SH.length-1]?.querySelector('#dm-property');if(path==='/api/host/new'&&options.form&&selector)options.form.set('property_type',selector.value);if(/^\/api\/host\/listing\/\d+$/.test(path)&&options.json&&selector)options.json.property_type=selector.value;return originalApi(path,options)};
document.addEventListener('click',async e=>{const service=e.target.closest('[data-service]');if(service){e.preventDefault();return switchService(service.dataset.service)}const mt=e.target.closest('[data-mtab]');if(mt){e.preventDefault();state.tab=mt.dataset.mtab;drawTabs();renderMarket();scrollTo(0,0);return}const dm=e.target.closest('[data-dm]');if(dm){e.preventDefault();const a=dm.dataset.dm;if(a==='home')go('search');if(a==='settings')settings();if(a==='safe')safety();if(a==='add'){if(state.service==='market')listingForm();else{if(!await auth())return;if(ME.role!=='host'){try{ME=await post('/api/register',{role:'host'});drawTabs()}catch(x){return onError(x)}}ACT.newl()}}if(a==='filters')filters();if(a==='refresh')renderMarket();if(a==='shipping')shippingSettings();if(a==='moderate')moderation();return}const cat=e.target.closest('[data-mcat]');if(cat){state.category=cat.dataset.mcat;searchMarket();return}const fav=e.target.closest('[data-mfav]');if(fav){e.preventDefault();favorite(Number(fav.dataset.mfav),fav);return}const listing=e.target.closest('[data-mid]');if(listing){openMarket(Number(listing.dataset.mid));return}const prof=e.target.closest('[data-mseller]');if(prof){seller(Number(prof.dataset.mseller));return}const ch=e.target.closest('[data-mchat]');if(ch){chat(Number(ch.dataset.mchat));return}const block=e.target.closest('[data-mblock]');if(block&&await auth()&&await confirm(t('blockConfirm'))){try{await request('/blocks','POST',{user_id:Number(block.dataset.mblock)});closeSheet();toast(t('saved'))}catch(x){onError(x)}}});
const privatePhotos=new Map();
document.addEventListener('error',async e=>{const img=e.target;if(!(img instanceof HTMLImageElement)||!img.src.includes('/api/market/photo/'))return;const url=img.src;img.style.display='none';if(ME.tg&&tg.initData){try{if(!privatePhotos.has(url))privatePhotos.set(url,fetch(url,{headers:{'X-Init':tg.initData}}).then(r=>{if(!r.ok)throw new Error();return r.blob()}).then(b=>URL.createObjectURL(b)));const objectURL=await privatePhotos.get(url);if(document.body.contains(img)){img.src=objectURL;img.style.display=''}return}catch(x){privatePhotos.delete(url)}}if(!document.body.contains(img))return;const placeholder=document.createElement('span');placeholder.className='mk-blank';placeholder.innerHTML=icon('photo');img.after(placeholder)},true);
async function moderation(){if(!ME.admin)return;const s=sheet(`<div class="pad mk-form"><h1 class="h1">${state.lang==='ru'?'Модерация':'Модерація'}</h1><div id="mm-list"><div class="sk" style="height:150px"></div></div></div>`,'plain');const list=s.querySelector('#mm-list');async function refresh(){try{const r=await request('/moderate');const pending=r.pending||[],reports=r.items||[];list.innerHTML=`<h2 class="h2">${state.lang==='ru'?'Ожидают проверки':'Очікують перевірки'} (${pending.length})</h2>${pending.map(l=>`<article class="mk-order"><b>${esc(l.title)}</b><p class="mk-help">#${l.id} · ${when(l.created)}</p><div class="mk-actions"><button class="cta g2" data-mid="${l.id}">${state.lang==='ru'?'Проверить':'Перевірити'}</button><button class="cta" data-moderate="${l.id}" data-status="active">${state.lang==='ru'?'Одобрить':'Схвалити'}</button><button class="cta g2" data-moderate="${l.id}" data-status="blocked">${t('block')}</button></div></article>`).join('')}<h2 class="h2">${state.lang==='ru'?'Жалобы':'Скарги'} (${reports.length})</h2>${reports.map(r=>`<article class="mk-order"><b>${esc(r.title)}</b><p class="mk-pre">${esc(r.reason)}</p><p class="mk-help">#${r.listing_id} · ${when(r.created)}</p><div class="mk-actions"><button class="cta g2" data-mid="${r.listing_id}">${state.lang==='ru'?'Проверить':'Перевірити'}</button><button class="cta g2" data-moderate="${r.listing_id}" data-status="active">${state.lang==='ru'?'Оставить':'Залишити'}</button><button class="cta" data-moderate="${r.listing_id}" data-status="blocked">${t('block')}</button></div></article>`).join('')}`;if(!pending.length&&!reports.length)list.innerHTML=`<div class="box">${state.lang==='ru'?'Новых задач нет':'Нових завдань немає'}</div>`}catch(e){list.innerHTML=`<div class="box">${esc(e.message)}</div>`}}s.addEventListener('click',async e=>{const b=e.target.closest('[data-moderate]');if(!b)return;b.disabled=true;try{await request('/moderate','POST',{listing_id:Number(b.dataset.moderate),status:b.dataset.status});await refresh()}catch(x){onError(x);b.disabled=false}});await refresh()}
const baseSheet=sheet,baseCloseSheet=closeSheet;sheet=function(html,cls=''){const s=baseSheet(html,cls);document.body.style.overflow='hidden';s.querySelector('.x')?.setAttribute('aria-label',t('close'));return s};closeSheet=function(s){baseCloseSheet(s);if(!SH.length)document.body.style.overflow=''};
