function translateFixed(value){if(rentalRussian[value])return rentalRussian[value];for(const [re,fn] of dynamicRental)if(re.test(value))return value.replace(re,fn);return value}
const originals=new WeakMap();let translateScheduled=false;
function translateRental(){if(state.service!=='rental')return;const nodes=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=nodes.nextNode()){const el=n.parentElement;if(!el||el.closest('script,style,.t,.mk-pre,.mk-name,.m,.mk-chat-messages,.dm-header,#tabs,input,textarea,[contenteditable],[data-user-content]'))continue;const raw=n.nodeValue,record=originals.get(n);const source=record&&record.rendered===raw?record.source:raw;const stripped=source.trim(),leading=source.slice(0,source.indexOf(stripped));let rendered=source;if(state.lang==='ru'){const translated=translateFixed(stripped);if(translated!==stripped)rendered=leading+translated+source.slice(source.indexOf(stripped)+stripped.length);else{const m=stripped.match(/^([\p{Emoji_Presentation}\p{Extended_Pictographic}\s✓✖+]+)(.+)$/u);if(m)rendered=leading+m[1]+translateFixed(m[2])+source.slice(source.indexOf(stripped)+stripped.length)}}if(raw!==rendered)n.nodeValue=rendered;originals.set(n,{source,rendered})}for(const el of document.querySelectorAll('input[placeholder],textarea[placeholder]')){const raw=el.getAttribute('placeholder'),key='dmOriginalPlaceholder';if(!el.dataset[key])el.dataset[key]=raw;const source=el.dataset[key];el.setAttribute('placeholder',state.lang==='ru'?(rentalRussian[source]||source):source)}}
const translator=new MutationObserver(()=>{if(translateScheduled)return;translateScheduled=true;requestAnimationFrame(()=>{translateScheduled=false;translateRental()})});translator.observe($('#view'),{childList:true,subtree:true,characterData:true});translator.observe($('#sheets'),{childList:true,subtree:true,characterData:true});
